package com.vidyavedika.auth.service;
import com.vidyavedika.auth.dto.AuthDtos.*; import com.vidyavedika.auth.entity.*; import com.vidyavedika.auth.repository.UserRepository; import com.vidyavedika.auth.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository repo; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;encoder=e;jwt=j;}
@Transactional public AuthResponse register(RegisterRequest req){if(repo.existsByEmail(req.email())) throw new IllegalArgumentException("Email already registered"); User u=new User();u.setName(req.name());u.setEmail(req.email().toLowerCase());u.setPassword(encoder.encode(req.password()));repo.save(u);return response(u);}
public AuthResponse login(LoginRequest req){User u=repo.findByEmail(req.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!u.isActive()||!encoder.matches(req.password(),u.getPassword()))throw new IllegalArgumentException("Invalid credentials");return response(u);} private AuthResponse response(User u){return new AuthResponse(jwt.generate(u.getId(),u.getEmail(),u.getRole().name()),"Bearer",u.getId(),u.getName(),u.getEmail(),u.getRole().name());}}
